const memoize = (fn) => {
  const cache = {};
  return (...args) => {
    const key = JSON.stringify(args);
    if (cache[key]) return cache[key];
    const result = fn(...args);
    cache[key] = result;
    return result;
  };
};

const factorial = memoize((n) => {
  if (n === 0 || n === 1) return 1;
  return n * factorial(n - 1);
});

