const rateLimiter = (limit, windowSize) => {
  const queue = [];
  return () => {
    const now = Date.now();
    while (queue.length && queue[0] <= now - windowSize) {
      queue.shift();
    }
    if (queue.length >= limit) return false;
    queue.push(now);
    return true;
  };
};

